const scrollProgressEl=document.getElementById("scrollProgress");function updateScrollProgress(){if(!scrollProgressEl)return;const e=window.scrollY||document.documentElement.scrollTop;const t=document.documentElement.scrollHeight-document.documentElement.clientHeight;const n=t>0?e/t*100:0;scrollProgressEl.style.width=n+"%"}window.addEventListener("scroll",updateScrollProgress,{passive:true});window.addEventListener("resize",updateScrollProgress);document.addEventListener("DOMContentLoaded",function(){updateScrollProgress();const e=document.querySelectorAll("nav a[href^='#']");if(e.length===0||!("IntersectionObserver"in window))return;const t=Array.from(e).map(function(e){return e.getAttribute("href").slice(1)});const n=t.map(function(e){return document.getElementById(e)}).filter(Boolean);function o(t){e.forEach(function(e){e.classList.toggle("nav-active",e.getAttribute("href")==="#"+t)})}const r=new IntersectionObserver(function(e){e.forEach(function(e){if(e.isIntersecting){o(e.target.id)}})},{rootMargin:"-45% 0px -45% 0px",threshold:0});n.forEach(function(e){r.observe(e)})});const footerYearEl=document.getElementById("footerYear");if(footerYearEl){footerYearEl.textContent=(new Date).getFullYear()}const themeToggleBtn=document.getElementById("themeToggle");const THEME_STORAGE_KEY="portfolio-theme";function applyThemeIcon(){if(!themeToggleBtn)return;const e=document.documentElement.getAttribute("data-theme")==="dark";themeToggleBtn.textContent=e?"☀️":"🌙"}if(themeToggleBtn){applyThemeIcon();themeToggleBtn.addEventListener("click",function(){const e=document.documentElement.getAttribute("data-theme")==="dark";if(e){document.documentElement.removeAttribute("data-theme");localStorage.setItem(THEME_STORAGE_KEY,"light")}else{document.documentElement.setAttribute("data-theme","dark");localStorage.setItem(THEME_STORAGE_KEY,"dark")}applyThemeIcon()})}document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".reveal");if(!("IntersectionObserver"in window)||e.length===0){e.forEach(function(e){e.classList.add("reveal-visible")});return}const t=new IntersectionObserver(function(e){e.forEach(function(e){if(e.isIntersecting){e.target.classList.add("reveal-visible");t.unobserve(e.target)}})},{threshold:.15,rootMargin:"0px 0px -40px 0px"});e.forEach(function(e){t.observe(e)})});
